// World textures (PNG files generated by tools/gen_textures.py) and particle sprites.
import * as THREE from '../lib/three.module.js';

const TEX_DIR = 'assets/textures/';

// Trilinear + anisotropic filtering: sharp up close, no shimmering in the distance.
function setupFiltering(t, anisotropy) {
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.magFilter = THREE.LinearFilter;
  t.minFilter = THREE.LinearMipmapLinearFilter;
  t.generateMipmaps = true;
  t.anisotropy = anisotropy;
  return t;
}

function loadTexture(loader, name, anisotropy) {
  return setupFiltering(loader.load(TEX_DIR + name), anisotropy);
}

function canvasTexture(w, h, draw, anisotropy = 1) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(c);
  t.magFilter = THREE.LinearFilter;
  t.minFilter = THREE.LinearMipmapLinearFilter;
  t.anisotropy = anisotropy;
  return t;
}

export function createTextures(renderer) {
  const anisotropy = renderer.capabilities.getMaxAnisotropy();
  const loader = new THREE.TextureLoader();

  const ground = loadTexture(loader, 'ground_albedo.png', anisotropy);
  const groundNormal = loadTexture(loader, 'ground_normal.png', anisotropy);
  for (const t of [ground, groundNormal]) t.repeat.set(40, 40);
  // lava pools: one tile covers ~4 m, the pool mesh scales its UVs to match
  const lava = loadTexture(loader, 'lava_albedo.png', anisotropy);
  const lavaNormal = loadTexture(loader, 'lava_normal.png', anisotropy);
  const lavaEmissive = loadTexture(loader, 'lava_emissive.png', anisotropy);

  const wall = loadTexture(loader, 'bricks_albedo.png', anisotropy);
  const wallNormal = loadTexture(loader, 'bricks_normal.png', anisotropy);
  const concrete = loadTexture(loader, 'concrete_albedo.png', anisotropy);
  const concreteNormal = loadTexture(loader, 'concrete_normal.png', anisotropy);

  // soft round particle
  const dot = canvasTexture(32, 32, g => {
    const gr = g.createRadialGradient(16, 16, 0, 16, 16, 16);
    gr.addColorStop(0, 'rgba(255,255,255,1)'); gr.addColorStop(0.5, 'rgba(255,255,255,0.8)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr; g.fillRect(0, 0, 32, 32);
  });

  const fire = canvasTexture(64, 64, g => {
    const gr = g.createRadialGradient(32, 32, 2, 32, 32, 30);
    gr.addColorStop(0, '#fffbe0'); gr.addColorStop(0.3, '#ffd040');
    gr.addColorStop(0.65, '#ff5a10'); gr.addColorStop(1, 'rgba(120,10,0,0)');
    g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
  });

  return { ground, groundNormal, lava, lavaNormal, lavaEmissive, wall, wallNormal, concrete, concreteNormal, dot, fire };
}
